    ('QMS_NCR_SOURCE', 'INSP',      'code.QMS_NCR_SOURCE.INSP',      1),
    ('QMS_NCR_SOURCE', 'SETUP',     'code.QMS_NCR_SOURCE.SETUP',     2),
    ('QMS_NCR_SOURCE', 'PROCESS',   'code.QMS_NCR_SOURCE.PROCESS',   3),
    ('QMS_NCR_SOURCE', 'CLAIM',     'code.QMS_NCR_SOURCE.CLAIM',     4),
