INSERT INTO sys_policy_def (policy_key, value_type, default_value, allowed_values, min_value, max_value, plant_scope_yn, desc_key) VALUES
    ('QMS_NCR_AUTO_HOLD', 'BOOL', 'Y', NULL, NULL, NULL, 'N', 'policy.QMS_NCR_AUTO_HOLD');

-- ---------------------------------------------------------------------
-- 1. 부적합
-- ---------------------------------------------------------------------
CREATE TABLE qms_ncr (
    ncr_id        bigint          GENERATED BY DEFAULT AS IDENTITY,
    comp_cd       varchar(20)     NOT NULL,
    ncr_no        varchar(30)     NOT NULL,
    source        varchar(10)     NOT NULL,
    lot_id        bigint          NOT NULL,
    item_id       bigint          NOT NULL,
    unit_cd       varchar(20)     NOT NULL,
    insp_id       bigint,
    defect_id     bigint          NOT NULL,
    nc_qty        numeric(18,3)   NOT NULL,
    description   varchar(2000)   NOT NULL,
    occurred_at   timestamptz     NOT NULL,
    status        varchar(10)     NOT NULL DEFAULT 'OPEN',
    hold_yn       char(1)         NOT NULL,
    apr_id        bigint,
    closed_at     timestamptz,
    closed_by     varchar(50),
    cancel_reason varchar(500),
    row_ver       integer         NOT NULL DEFAULT 0,
    created_at    timestamptz     NOT NULL DEFAULT now(),
    created_by    varchar(50)     NOT NULL,
    updated_at    timestamptz     NOT NULL DEFAULT now(),
    updated_by    varchar(50)     NOT NULL,
    CONSTRAINT pk_qms_ncr PRIMARY KEY (ncr_id),
    CONSTRAINT fk_qms_ncr_comp FOREIGN KEY (comp_cd) REFERENCES sys_comp (comp_cd),
    CONSTRAINT fk_qms_ncr_lot FOREIGN KEY (lot_id) REFERENCES lot_master (lot_id),
    CONSTRAINT fk_qms_ncr_item FOREIGN KEY (item_id) REFERENCES mst_item (item_id),
    CONSTRAINT fk_qms_ncr_insp FOREIGN KEY (insp_id) REFERENCES qms_insp (insp_id),
    CONSTRAINT fk_qms_ncr_defect FOREIGN KEY (defect_id) REFERENCES qms_defect (defect_id),
    CONSTRAINT fk_qms_ncr_apr FOREIGN KEY (apr_id) REFERENCES apr_request (apr_id),
    CONSTRAINT uq_qms_ncr_no UNIQUE (comp_cd, ncr_no),
    CONSTRAINT ck_qms_ncr_source CHECK (source IN ('INSP', 'SETUP', 'PROCESS', 'CLAIM', 'OTHER')),
    CONSTRAINT ck_qms_ncr_status CHECK (status IN ('OPEN', 'PENDING', 'CLOSED', 'CANCELLED')),
    CONSTRAINT ck_qms_ncr_qty CHECK (nc_qty > 0),
    CONSTRAINT ck_qms_ncr_desc CHECK (length(btrim(description)) > 0),
    CONSTRAINT ck_qms_ncr_hold CHECK (hold_yn IN ('Y', 'N')),
    CONSTRAINT ck_qms_ncr_pending CHECK (status <> 'PENDING' OR apr_id IS NOT NULL),
    CONSTRAINT ck_qms_ncr_closed CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL) AND (closed_at IS NULL) = (closed_by IS NULL)),
    CONSTRAINT ck_qms_ncr_cancel CHECK ((status = 'CANCELLED') = (coalesce(length(btrim(cancel_reason)), 0) > 0))
);
CREATE INDEX ix_qms_ncr_lot ON qms_ncr (comp_cd, lot_id);
CREATE INDEX ix_qms_ncr_created ON qms_ncr (comp_cd, created_at DESC);
COMMENT ON TABLE qms_ncr IS '부적합(NCR) — LOT·불량 유형·수량, OPEN → (PENDING 특채 결재) → CLOSED / CANCELLED, LOT 보류는 MES LotHoldPort (docs/29_P3 Q8a)';
COMMENT ON COLUMN qms_ncr.hold_yn IS '등록 때 이 NCR 근거로 LOT 을 보류했는지(정책 QMS_NCR_AUTO_HOLD) — 종결·취소 때 같은 근거를 해제';
COMMENT ON COLUMN qms_ncr.ncr_id IS 'GENERATED BY DEFAULT — 서비스가 시퀀스에서 먼저 받아 LOT 보류(포트) 뒤 INSERT(잠금 순서 LOT → qms_ncr)';

CREATE FUNCTION hb_guard_qms_ncr() RETURNS trigger
    LANGUAGE plpgsql
AS $$
DECLARE
    v_lot   lot_master;
    v_insp  qms_insp;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'NCR cannot be deleted (cancel it)' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_no_delete';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'OPEN' THEN
            RAISE EXCEPTION 'new NCR must be OPEN' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_open';
        END IF;
        -- 잠금 없이 읽기(LOT 은 포트가 이미 잠갔거나 보류하지 않는 경우)
        SELECT * INTO v_lot FROM lot_master WHERE lot_id = NEW.lot_id AND comp_cd = NEW.comp_cd;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'lot % does not belong to company %', NEW.lot_id, NEW.comp_cd USING ERRCODE = '23503', CONSTRAINT = 'fk_qms_ncr_lot_comp';
        END IF;
        IF v_lot.item_id <> NEW.item_id OR v_lot.unit_cd <> NEW.unit_cd THEN
            RAISE EXCEPTION 'item and unit must be copied from the lot' USING ERRCODE = '23514', CONSTRAINT = 'ck_qms_ncr_lot_copy';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM qms_defect d WHERE d.defect_id = NEW.defect_id AND d.comp_cd = NEW.comp_cd) THEN
            RAISE EXCEPTION 'defect % does not belong to company %', NEW.defect_id, NEW.comp_cd
                USING ERRCODE = '23503', CONSTRAINT = 'fk_qms_ncr_defect_comp';
        END IF;
        IF NEW.insp_id IS NOT NULL THEN
            SELECT * INTO v_insp FROM qms_insp WHERE insp_id = NEW.insp_id AND comp_cd = NEW.comp_cd;
            IF NOT FOUND OR v_insp.lot_id <> NEW.lot_id OR v_insp.status <> 'JUDGED' THEN
                RAISE EXCEPTION 'evidence inspection must be a judged inspection of the same lot'
                    USING ERRCODE = '23514', CONSTRAINT = 'ck_qms_ncr_insp';
            END IF;
        END IF;
        RETURN NEW;
    END IF;
    -- UPDATE: 정체(번호·출처·LOT·근거·보류 여부·만든 기록)는 고정, 내용은 OPEN 동안만, 전이는 정해진 길만
    IF (NEW.comp_cd, NEW.ncr_no, NEW.source, NEW.lot_id, NEW.item_id, NEW.unit_cd, NEW.insp_id, NEW.hold_yn, NEW.created_at, NEW.created_by)
       IS DISTINCT FROM (OLD.comp_cd, OLD.ncr_no, OLD.source, OLD.lot_id, OLD.item_id, OLD.unit_cd, OLD.insp_id, OLD.hold_yn, OLD.created_at,
                         OLD.created_by) THEN
        RAISE EXCEPTION 'NCR identity is fixed' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_immutable';
    END IF;
    IF OLD.status IN ('CLOSED', 'CANCELLED')
       OR (OLD.status = 'PENDING' AND NEW.status NOT IN ('OPEN', 'CLOSED'))
       OR (OLD.status = 'OPEN' AND NEW.status NOT IN ('OPEN', 'PENDING', 'CLOSED', 'CANCELLED')) THEN
        RAISE EXCEPTION 'NCR % cannot move from % to %', OLD.ncr_id, OLD.status, NEW.status USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_transition';
    END IF;
    IF OLD.status <> 'OPEN' AND (NEW.defect_id, NEW.nc_qty, NEW.description, NEW.occurred_at)
       IS DISTINCT FROM (OLD.defect_id, OLD.nc_qty, OLD.description, OLD.occurred_at) THEN
        RAISE EXCEPTION 'NCR % content can only change while OPEN', OLD.ncr_id USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_immutable';
    END IF;
    IF NEW.defect_id IS DISTINCT FROM OLD.defect_id
       AND NOT EXISTS (SELECT 1 FROM qms_defect d WHERE d.defect_id = NEW.defect_id AND d.comp_cd = NEW.comp_cd) THEN
        RAISE EXCEPTION 'defect % does not belong to company %', NEW.defect_id, NEW.comp_cd USING ERRCODE = '23503', CONSTRAINT = 'fk_qms_ncr_defect_comp';
    END IF;
    -- 종결·상신은 처분 수량 합 = 부적합 수량일 때만
    IF NEW.status IN ('PENDING', 'CLOSED') AND OLD.status = 'OPEN'
       AND coalesce((SELECT sum(qty) FROM qms_ncr_disp WHERE ncr_id = NEW.ncr_id), 0) <> NEW.nc_qty THEN
        RAISE EXCEPTION 'disposition quantities must add up to the NCR quantity' USING ERRCODE = '23514', CONSTRAINT = 'ck_qms_ncr_disp_sum';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER tg_qms_ncr_guard BEFORE INSERT OR UPDATE OR DELETE ON qms_ncr FOR EACH ROW EXECUTE FUNCTION hb_guard_qms_ncr();
CREATE TRIGGER tg_audit AFTER INSERT OR UPDATE OR DELETE ON qms_ncr FOR EACH ROW EXECUTE FUNCTION hb_audit('ncr_id', '', '');

ALTER TABLE qms_ncr ENABLE ROW LEVEL SECURITY;
ALTER TABLE qms_ncr FORCE  ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON qms_ncr USING (comp_cd = hb_current_comp()) WITH CHECK (comp_cd = hb_current_comp());
REVOKE DELETE, TRUNCATE ON qms_ncr FROM ${app_role};

-- ---------------------------------------------------------------------
-- 2. 처분 행
-- ---------------------------------------------------------------------
CREATE TABLE qms_ncr_disp (
    disp_id        bigint          GENERATED ALWAYS AS IDENTITY,
    comp_cd        varchar(20)     NOT NULL,
    ncr_id         bigint          NOT NULL,
    line_no        integer         NOT NULL,
    disp_type      varchar(10)     NOT NULL,
    qty            numeric(18,3)   NOT NULL,
    note           varchar(500),
    rework_lot_no  varchar(50),
    created_at     timestamptz     NOT NULL DEFAULT now(),
    created_by     varchar(50)     NOT NULL,
    CONSTRAINT pk_qms_ncr_disp PRIMARY KEY (disp_id),
    CONSTRAINT fk_qms_ncr_disp_comp FOREIGN KEY (comp_cd) REFERENCES sys_comp (comp_cd),
    CONSTRAINT fk_qms_ncr_disp_ncr FOREIGN KEY (ncr_id) REFERENCES qms_ncr (ncr_id),
    CONSTRAINT uq_qms_ncr_disp_line UNIQUE (ncr_id, line_no),
    CONSTRAINT ck_qms_ncr_disp_type CHECK (disp_type IN ('USE_AS_IS', 'REWORK', 'SCRAP', 'RETURN', 'SORT')),
    CONSTRAINT ck_qms_ncr_disp_qty CHECK (qty > 0),
    CONSTRAINT ck_qms_ncr_disp_rework CHECK (rework_lot_no IS NULL OR disp_type = 'REWORK')
);
COMMENT ON TABLE qms_ncr_disp IS 'NCR 처분 행(MRB) — NCR OPEN 동안만 고침, 수량 합 = 부적합 수량이어야 종결·상신 (docs/29_P3 Q8a)';
COMMENT ON COLUMN qms_ncr_disp.rework_lot_no IS '재작업 결과 LOT 번호(참조만 — 실제 재작업은 MES LOT 재작업)';

CREATE FUNCTION hb_guard_qms_ncr_disp() RETURNS trigger
    LANGUAGE plpgsql
AS $$
DECLARE
    v_ncr  bigint := CASE WHEN TG_OP = 'DELETE' THEN OLD.ncr_id ELSE NEW.ncr_id END;
    v_comp varchar := CASE WHEN TG_OP = 'DELETE' THEN OLD.comp_cd ELSE NEW.comp_cd END;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'disposition lines are replaced, not updated' USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_disp_no_update';
    END IF;
    -- NCR 머리를 잠그고 OPEN 확인(서비스도 머리를 먼저 잠근다 — 같은 순서)
    PERFORM 1 FROM qms_ncr n WHERE n.ncr_id = v_ncr AND n.comp_cd = v_comp AND n.status = 'OPEN' FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'NCR % is not open in company %', v_ncr, v_comp USING ERRCODE = '55000', CONSTRAINT = 'ck_qms_ncr_disp_open';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;
CREATE TRIGGER tg_qms_ncr_disp_guard BEFORE INSERT OR UPDATE OR DELETE ON qms_ncr_disp FOR EACH ROW EXECUTE FUNCTION hb_guard_qms_ncr_disp();
CREATE TRIGGER tg_audit AFTER INSERT OR UPDATE OR DELETE ON qms_ncr_disp FOR EACH ROW EXECUTE FUNCTION hb_audit('disp_id', '', '');

ALTER TABLE qms_ncr_disp ENABLE ROW LEVEL SECURITY;
ALTER TABLE qms_ncr_disp FORCE  ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON qms_ncr_disp USING (comp_cd = hb_current_comp()) WITH CHECK (comp_cd = hb_current_comp());
REVOKE TRUNCATE ON qms_ncr_disp FROM ${app_role};

-- ---------------------------------------------------------------------
-- 3. 8D 연결(1부 자리) — FK + 같은 회사
-- ---------------------------------------------------------------------
ALTER TABLE qms_capa ADD CONSTRAINT fk_qms_capa_ncr FOREIGN KEY (ncr_id) REFERENCES qms_ncr (ncr_id);
COMMENT ON COLUMN qms_capa.ncr_id IS '부적합(NCR) 연결 — FK + 같은 회사 확인(docs/29_P3 Q8a)';

CREATE FUNCTION hb_check_qms_capa_ncr() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.ncr_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.ncr_id IS DISTINCT FROM OLD.ncr_id)
       AND NOT EXISTS (SELECT 1 FROM qms_ncr n WHERE n.ncr_id = NEW.ncr_id AND n.comp_cd = NEW.comp_cd) THEN
        RAISE EXCEPTION 'NCR % does not belong to company %', NEW.ncr_id, NEW.comp_cd USING ERRCODE = '23503', CONSTRAINT = 'fk_qms_capa_ncr_comp';
    END IF;
    RETURN NEW;
END
$$;
CREATE TRIGGER tg_qms_capa_ncr BEFORE INSERT OR UPDATE ON qms_capa FOR EACH ROW EXECUTE FUNCTION hb_check_qms_capa_ncr();

INSERT INTO sys_prog (prog_cd, prog_nm_key, view_path, module_cd, actions, sort_no) VALUES
    ('qms-ncr', 'prog.qmsNcr', 'qms/ncr', 'QMS', ARRAY['SEARCH','SAVE','DELETE']::varchar(20)[], 697);
INSERT INTO sys_retention_table (table_nm, class_cd) VALUES ('qms_ncr', 'QUALITY_RECORD'), ('qms_ncr_disp', 'QUALITY_RECORD');
